using System;
using System.Threading.Tasks;

class AsyncLambdas
{
    static Func<int, int, Task<int>> Sum = async (x, y) => { await Task.Yield(); return x + y; };
    static Func<int, Task> Wait = async x => await Task.Delay(x);
    static Func<int, int, int> Fixed = static (x, y) => x - y;
}

