class Patterns
{
    static int First(int[] values) => values switch
    {
        [var head, ..] => head,
        [] => -1,
        _ => 0,
    };

    static bool StartsWithOne(int[] values) => values is [1, .. var rest] && rest.Length > 0;
}

class Counter
{
    public int Value;

    public void operator +=(int amount) => Value += amount;
    public void operator <<=(int shift) => Value <<= shift;
}

class Holder
{
    public Holder Next;
    public int Value;

    static void Set(Holder h)
    {
        h?.Value = 1;
        h?.Next?.Value = 2;
    }
}

